function serverWorkflowForm(params) {
  // Async (CMP registers it with isAsync). Runs once when the Run Workflow
  // form loads, then watches the Workflow dropdown. For each workflow chosen
  // it asks the Server Workflows webhook for the workflow's steps and the
  // inputs it asks for, rebuilds the action-input.workflow_inputs Dynamic
  // Panel from them (one panel per step), lists the steps, and shows a
  // credentials box when CloudBolt has no way to log in to the server for a
  // script step. The box is plain HTML, not survey questions, so the password
  // never joins the submitted payload (CloudBolt writes that to the job log);
  // the webhook saves it on the server instead, as CloudBolt's own credential
  // prompt does.
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  if (survey.cbServerWorkflowForm) { done("ready"); return; }
  survey.cbServerWorkflowForm = true;

  var HOOK = "/api/v3/cmp/inboundWebHooks/server-workflows/run/";
  var WORKFLOW = "action-input.workflow";
  var PANEL = "action-input.workflow_inputs";
  var NOTE = "server_workflow_note";
  var state = { workflow: null, blocking: "", credentials: null, request: 0 };

  function escapeHtml(value) {
    return String(value === undefined || value === null ? "" : value)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function paragraph(text, css) {
    return "<p" + (css ? " class=\"" + css + "\"" : "") + ">" + escapeHtml(text) + "</p>";
  }
  function query(values) {
    return Object.keys(values).map(function (key) {
      var value = values[key];
      return encodeURIComponent(key) + "=" + encodeURIComponent(value === undefined || value === null ? "" : value);
    }).join("&");
  }
  function serverIds() {
    var ids = survey.getValue("object_ids");
    return typeof ids === "string" ? ids : (ids ? JSON.stringify(ids) : "");
  }
  function readJson(response) {
    return response.text().then(function (text) {
      var body;
      try { body = JSON.parse(text); } catch (e) { body = { error: "non-JSON reply (HTTP " + response.status + "): " + text.slice(0, 300) }; }
      if (!body || typeof body !== "object") body = { error: "unexpected reply (HTTP " + response.status + ")" };
      if (!response.ok && !body.error) body.error = "HTTP " + response.status;
      return body;
    });
  }
  function setNote(html) {
    var note = survey.getQuestionByName(NOTE);
    if (!note) return;
    note.html = html || "";
    note.visible = !!html;
  }

  function replacePanel(spec) {
    var old = survey.getQuestionByName(PANEL);
    var container = old && old.parent ? old.parent : survey.pages[0];
    var index = old ? container.elements.indexOf(old) : container.elements.length;
    var elements = (spec && spec.elements) || [];
    // Built in full before it joins the page, so the first render has every property.
    var panel = Survey.Serializer.createClass("paneldynamic");
    panel.name = PANEL;
    panel.fromJSON({
      title: "Workflow inputs",
      description: "What the workflow's steps ask for. Everything else is set in the workflow.",
      templateElements: elements,
      maxPanelCount: 1,
      allowAddPanel: false,
      allowRemovePanel: false
    });
    if (old) container.removeElement(old);
    container.addElement(panel, index);
    panel.panelCount = elements.length ? 1 : 0;
    panel.minPanelCount = elements.length ? 1 : 0;
    panel.visible = elements.length > 0;
  }

  function stepsHtml(spec) {
    var steps = spec.steps || [];
    if (!steps.length) return "";
    var items = steps.map(function (step) {
      return "<li><strong>" + escapeHtml(step.name) + "</strong> <span class=\"text-muted\">(" +
        escapeHtml(step.type) + ": " + escapeHtml(step.action) + ")</span></li>";
    }).join("");
    var lead = spec.description ? paragraph(spec.description) : "";
    return "<div class=\"cb-server-workflow-steps\">" + lead + "<p>Runs these steps in order:</p><ol>" + items + "</ol></div>";
  }

  function credentialsHtml(info) {
    var hosts = (info.needed || []).join(", ");
    if (!info.can_save) {
      return paragraph("CloudBolt has no credentials to log in to " + hosts + " for this workflow's scripts. Ask an " +
        "administrator to set them on the server or on the Remote Scripts, then run the workflow.", "text-danger");
    }
    return "<div class=\"cb-server-workflow-credentials\">" +
      paragraph("CloudBolt has no credentials to log in to " + hosts + " for this workflow's scripts. Save a username " +
        "and password on the server (stored encrypted, and used by this and later runs):") +
      "<div class=\"mb-2\"><label class=\"form-label\" for=\"cb-server-workflow-username\">Username</label>" +
      "<input type=\"text\" class=\"form-control\" id=\"cb-server-workflow-username\" autocomplete=\"off\"></div>" +
      "<div class=\"mb-2\"><label class=\"form-label\" for=\"cb-server-workflow-password\">Password</label>" +
      "<input type=\"password\" class=\"form-control\" id=\"cb-server-workflow-password\" autocomplete=\"new-password\"></div>" +
      "<button type=\"button\" class=\"sd-btn sd-btn--action\" id=\"cb-server-workflow-save\">Save credentials</button> " +
      "<span id=\"cb-server-workflow-save-status\"></span></div>";
  }

  function load(workflow) {
    var mine = ++state.request;
    state.workflow = workflow || null;
    state.blocking = "";
    state.credentials = null;
    if (!workflow) { replacePanel(null); setNote(""); return; }
    setNote(paragraph("Loading the workflow...", "custom-order-form-loading"));
    fetch(HOOK + "?" + query({ source: "prompts", server: survey.getValue("object_id"), servers: serverIds(), workflow: workflow }), {
      credentials: "same-origin", headers: { "Accept": "application/json" }
    })
      .then(readJson)
      .then(function (reply) {
        if (mine !== state.request) return;
        if (reply.error || !reply.panel) {
          replacePanel(null);
          state.blocking = reply.error || "Could not load the workflow.";
          setNote(paragraph(state.blocking, "text-danger"));
          return;
        }
        var spec = reply.panel;
        replacePanel(spec);
        var notes = [stepsHtml(spec)];
        if (spec.blocking && spec.blocking.length) {
          state.blocking = spec.blocking.join(" ");
          spec.blocking.forEach(function (reason) { notes.push(paragraph(reason, "text-danger")); });
        }
        if (!spec.elements || !spec.elements.length) {
          notes.push(paragraph("This workflow asks for nothing: Run starts it."));
        }
        var credentials = reply.credentials || {};
        if (credentials.needed && credentials.needed.length) {
          state.credentials = credentials;
          notes.push(credentialsHtml(credentials));
        }
        setNote(notes.join(""));
      })
      .catch(function (error) {
        if (mine !== state.request) return;
        state.blocking = "Could not load the workflow: " + error;
        setNote(paragraph(state.blocking, "text-danger"));
      });
  }

  function saveCredentials() {
    var username = document.getElementById("cb-server-workflow-username");
    var password = document.getElementById("cb-server-workflow-password");
    var status = document.getElementById("cb-server-workflow-save-status");
    var csrf = window.c2 && window.c2.settings ? window.c2.settings.CSRFToken : "";
    if (status) status.textContent = "Saving...";
    fetch(HOOK, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json", "Accept": "application/json", "X-CSRFToken": csrf },
      body: JSON.stringify({
        source: "credentials",
        server: String(survey.getValue("object_id") || ""),
        username: username ? username.value : "",
        password: password ? password.value : ""
      })
    })
      .then(readJson)
      .then(function (reply) {
        if (password) password.value = "";
        if (reply.error || !reply.saved) {
          if (status) status.textContent = "Not saved: " + (reply.error || "unexpected reply");
          return;
        }
        load(state.workflow);
      })
      .catch(function (error) {
        if (password) password.value = "";
        if (status) status.textContent = "Not saved: " + error;
      });
  }

  // The workflow list comes from the webhook too, not choicesByUrl: CMP adds
  // the object_ids question only on bulk runs, and a choicesByUrl URL that
  // names a missing question is never requested. CMP also adds object_id
  // after the survey is built, so wait for it.
  function loadWorkflows(attempt) {
    var question = survey.getQuestionByName(WORKFLOW);
    var objectId = survey.getValue("object_id");
    if (!question) return;
    if (!objectId) {
      if (attempt < 40) { setTimeout(function () { loadWorkflows(attempt + 1); }, 250); return; }
      setNote(paragraph("The form did not receive the server's id (object_id).", "text-danger"));
      return;
    }
    question.placeholder = "Loading workflows...";
    fetch(HOOK + "?" + query({ source: "workflows", server: objectId, servers: serverIds() }), {
      credentials: "same-origin", headers: { "Accept": "application/json" }
    })
      .then(readJson)
      .then(function (reply) {
        var options = reply.options || [];
        question.choices = options.map(function (option) { return { value: option.value, text: option.title }; });
        question.placeholder = options.length ? "Select a workflow..." : "No workflows fit this server";
        if (reply.error) setNote(paragraph("Could not load the workflows: " + reply.error, "text-danger"));
      })
      .catch(function (error) {
        question.placeholder = "Select...";
        setNote(paragraph("Could not load the workflows: " + error, "text-danger"));
      });
  }

  document.addEventListener("click", function (event) {
    if (!event.target || event.target.id !== "cb-server-workflow-save") return;
    event.preventDefault();
    saveCredentials();
  });
  survey.onValueChanged.add(function (sender, options) {
    if (options.name === WORKFLOW) load(options.value);
  });
  survey.onValidateQuestion.add(function (sender, options) {
    if (options.name !== WORKFLOW || !options.value || options.value !== state.workflow) return;
    if (state.blocking) {
      options.error = state.blocking;
    } else if (state.credentials) {
      options.error = "CloudBolt has no credentials for " + state.credentials.needed.join(", ") +
        ". Save them above, or ask an administrator to set them.";
    }
  });
  loadWorkflows(0);
  if (survey.getValue(WORKFLOW)) load(survey.getValue(WORKFLOW));
  done("ready");
}
